using System;
class C
{
    public unsafe static void Main()
    {
        void* ptr = (void*)ulong.MaxValue;

        try
        {
            IntPtr i = checked((IntPtr)ptr);
        }
        catch (System.OverflowException)
        {
            Console.Write("OVERFLOW ");
        }

        IntPtr j = unchecked((IntPtr)ptr);
        if (j == (IntPtr)(-1))
        {
            Console.Write("RAN");
        }
    }
}
